package io.github.astelev.around_planet.space;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class SolarSystemTest {
 private final CelestialSystem s=new CelestialSystem(20000,9.81*20000*20000,0);
 @Test void hierarchyContainsLunarSphere(){assertTrue(s.earthSoi()>s.distance()+s.soi());assertTrue(s.earthDistance()-s.earthSoi()>s.solarDestructionRadius());}
 @Test void allFramesRoundTripPositionAndVelocity(){var state=new SpaceState(new SpaceVector(10000,-40000,22000),new SpaceVector(100,-20,30));for(var primary:new String[]{CelestialSystem.SUN,CelestialSystem.EARTH,CelestialSystem.MOON})for(long tick:new long[]{0,100000,10000000}){var restored=s.relative(primary,s.global(primary,state,tick),tick);assertTrue(restored.position().subtract(state.position()).length()<1e-7);assertTrue(restored.velocity().subtract(state.velocity()).length()<1e-9);}}
 @Test void earthEscapeAndReturnPreserveHeliocentricMomentum(){long t=12345;var p=new SpaceState(new SpaceVector(s.earthSoi()+10,0,0),new SpaceVector(300,20,0));var earth=new SpaceTrajectory(CelestialSystem.EARTH,t,p,s.earthMu());var solar=PatchedConics.change(earth,t,s);assertEquals(CelestialSystem.SUN,solar.primary());assertTrue(s.global(earth.primary(),p,t).position().subtract(solar.at(t).position()).length()<1e-8);assertTrue(s.global(earth.primary(),p,t).velocity().subtract(solar.at(t).velocity()).length()<1e-8);var restored=PatchedConics.change(solar,t,s);assertEquals(CelestialSystem.EARTH,restored.primary());assertTrue(restored.at(t).velocity().subtract(p.velocity()).length()<1e-8);}
 @Test void solarClockAndSunlightAreSynchronized(){long quarter=Math.round(s.solarPeriod()*20/4);var sun=s.sunlight(CelestialSystem.EARTH,SpaceVector.ZERO,quarter);assertTrue(sun.x()>.9999);assertEquals(s.earth(quarter),s.warp(quarter).earth(0));var relativeSun=new PlanetSpin(s.solarAngle(quarter),s.solarMotion()).unrotate(sun);assertTrue(relativeSun.subtract(SpaceEnvironment.SUN_DIRECTION).length()<1e-10);}
 @Test void sunChartShowsNestedOrbitsWithoutLeakingOuterOrbitsIntoLocalCharts(){assertTrue(OrbitChart.visible(CelestialSystem.EARTH,CelestialSystem.SUN));assertTrue(OrbitChart.visible(CelestialSystem.MOON,CelestialSystem.SUN));assertFalse(OrbitChart.visible(CelestialSystem.SUN,CelestialSystem.EARTH));assertFalse(OrbitChart.visible(CelestialSystem.EARTH,CelestialSystem.MOON));}
 @Test void movingEarthEncounterIsFoundInSolarCoordinates(){long encounter=100000;var e=s.earth(encounter);var near=new SpaceState(e.position().add(new SpaceVector(s.earthSoi(),0,0)),e.velocity().add(new SpaceVector(-600,0,0)));var at=new SpaceTrajectory(CelestialSystem.SUN,encounter,near,s.sunMu());var path=new SpaceTrajectory(CelestialSystem.SUN,encounter-2000,at.at(encounter-2000),s.sunMu());long t=PatchedConics.transition(path,encounter-2000,encounter+2000,s);assertTrue(t>encounter-2000&&t<=encounter+2,"Missed moving Earth SOI: "+t);}
 @Test void solarFallClipsPredictionAndTimeWarpAndPersistsDeletion(){double radius=s.solarDestructionRadius()*2;var path=new SpaceTrajectory(CelestialSystem.SUN,0,new SpaceState(new SpaceVector(radius,0,0),new SpaceVector(-2000,10,0)),s.sunMu());long hit=PatchedConics.solarContact(path,0,1000000,s);assertTrue(hit>0);var flight=PatchedConics.trace(path,0,1000000,s);assertTrue(flight.solarImpact());assertEquals(hit,flight.legs().getLast().until());var preview=ManeuverPreview.create(path,0,java.util.List.of(),s.sunRadius(),s.solarDestructionRadius()-s.sunRadius(),s,6);assertTrue(preview.segments().getLast().points().getLast().tick()<=hit+1);}

 @Test void circularSolarCoastDoesNotTriggerSolarImpact(){double radius=s.earthDistance()/2;var path=new SpaceTrajectory(CelestialSystem.SUN,0,new SpaceState(new SpaceVector(radius,0,0),new SpaceVector(0,Math.sqrt(s.sunMu()/radius),0)),s.sunMu());assertEquals(-1,PatchedConics.solarContact(path,0,1000000000000L,s));}

}
